# Complete script to generate verifiedHindiAnimeCatalogExpanded.ts

def load_existing():
    titles = set()
    try:
        with open('src/services/verifiedHindiAnimeCatalog.ts', 'r', encoding='utf-8') as f:
            for line in f:
                if 'title:' in line:
                    t = line.split('title:')[1].split(',')[0].strip().strip("'\"")
                    titles.add(t.lower())
    except Exception as e:
        print('Error reading existing catalog:', e)
    return titles

existing_titles = load_existing()
print(f"Existing catalog count: {len(existing_titles)}")

